style.css:
/* Google SlayStation™ */
:root {
  /* swap these colors if you want */
  --my-pink: #ff4fa3;
  --my-purple: #a855f7;
  --my-bg: #fff0fa;
  --my-text: #64104c;
}

/* main background */
body {
  background: linear-gradient(135deg, #ffe0f2, #f3dcff, #fff0fa) !important;
  color: var(--my-text) !important;
}

/* search box */
textarea,
input[type="text"] {
  border: 3px solid var(--my-pink) !important;
  border-radius: 30px !important;
  background: #fff7fc !important;
  box-shadow: 0 5px 20px #ff4fa344 !important;
}

/* buttons */
button,
input[type="submit"] {
  border-radius: 25px !important;
  border: 2px solid var(--my-pink) !important;
  background: linear-gradient(135deg, var(--my-pink), var(--my-purple)) !important;
  color: white !important;
  font-weight: 900 !important;
}

/* links */
a {
  color: #d63391 !important;
}

/* images */
img {
  border-radius: 12px !important;
}
